options.customCss:
:root {
  /* Brand Colors */
  --chat--color-primary: #e98a28; /* Tahayyul Orange */
  --chat--color-primary-shade-50: #d87e1f;
  --chat--color-primary-shade-100: #c76f15;
  --chat--color-secondary: #20b69e;
  --chat--color-secondary-shade-50: #1ca08a;
  --chat--color-white: #ffffff;
  --chat--color-light: #fef9f4;
  --chat--color-light-shade-50: #f4e8db;
  --chat--color-light-shade-100: #e3d3be;
  --chat--color-medium: #c8b9a6;
  --chat--color-dark: #2b1d0e;
  --chat--color-disabled: #999;
  --chat--color-typing: #5c5c5c;

  /* Layout & Dimensions */
  --chat--spacing: 1rem;
  --chat--border-radius: 1rem;
  --chat--transition-duration: 0.15s;
  --chat--font-family: (
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    Roboto,
    Oxygen-Sans,
    Ubuntu,
    Cantarell,
    'Helvetica Neue',
    sans-serif
  );

  --chat--window--width: 340px;
  --chat--window--height: 520px;
  --chat--window--z-index: 9999;
  --chat--window--bottom: 50%;
  --chat--window--right: 50%;
  --chat--window--margin-bottom: -260px; /* Half of height for perfect vertical center */
  --chat--window--margin-right: -170px; /* Half of width for perfect horizontal center */
  --chat--window--border: 2px solid var(--chat--color-primary-shade-50);
  --chat--window--border-radius: var(--chat--border-radius);

  /* Header */
  --chat--header-height: auto;
  --chat--header--padding: var(--chat--spacing);
  --chat--header--background: var(--chat--color-primary);
  --chat--header--color: var(--chat--color-white);
  --chat--heading--font-size: 1.5em;
  --chat--subtitle--font-size: 1em;
  --chat--subtitle--line-height: 1.6;

  /* Messages */
  --chat--message--font-size: 0.95rem;
  --chat--message--padding: 0.8rem;
  --chat--message--border-radius: 0.75rem;
  --chat--message-line-height: 1.4;
  --chat--message--margin-bottom: 0.75rem;
  --chat--message--bot--background: var(--chat--color-white);
  --chat--message--bot--color: var(--chat--color-dark);
  --chat--message--user--background: var(--chat--color-primary);
  --chat--message--user--color: var(--chat--color-white);

  /* Input */
  --chat--textarea--height: 48px;
  --chat--input--font-size: 0.95rem;
  --chat--input--background: var(--chat--color-white);
  --chat--input--padding: 0.75rem;
  --chat--input--border: 1px solid var(--chat--color-light-shade-100);

  /* Button */
  --chat--button--background: var(--chat--color-primary);
  --chat--button--color: var(--chat--color-white);
  --chat--button--hover--background: var(--chat--color-primary-shade-50);
  --chat--button--border-radius: var(--chat--border-radius);

  /* Toggle Button */
  --chat--toggle--size: 56px;
  --chat--toggle--background: var(--chat--color-primary);
  --chat--toggle--color: var(--chat--color-white);
  --chat--toggle--hover--background: var(--chat--color-primary-shade-50);

  /* Background */
  --chat--body--background: var(--chat--color-light);
  --chat--footer--background: var(--chat--color-light);
  --chat--footer--color: var(--chat--color-dark);
}

/* Chat Message Width */
.chat-message {
  max-width: 85%;
}
